package com.mytransitgps.modules.ciq.collector;
import com.mytransitgps.modules.ciq.client.LtaVmsClient;import com.mytransitgps.modules.ciq.config.CiqProperties;import com.mytransitgps.modules.ciq.domain.VmsRecord;import com.mytransitgps.modules.ciq.parser.VmsParser;import com.mytransitgps.modules.ciq.persistence.*;import com.mytransitgps.modules.ciq.quality.VmsValidator;import com.mytransitgps.modules.ciq.storage.*;import com.mytransitgps.platform.collection.*;import org.slf4j.*;
/** API04 独立 Collector。 */
public class CiqVmsCollector implements DataCollector {private static final Logger log=LoggerFactory.getLogger(CiqVmsCollector.class);private final CiqPagedJsonCollectorSupport<VmsRecord> support;public CiqVmsCollector(LtaVmsClient client,CiqProperties p,CiqJsonStorageService storage,VmsParser parser,VmsValidator validator,VmsPersistenceService persistence,CiqAuditPersistenceService audit){support=new CiqPagedJsonCollectorSupport<>("API04",CiqApiCode.API04,CollectorCode.CIQ_VMS,client,p,p.getCollectors().getVms(),storage,parser::parse,validator::isValid,persistence==null?null:persistence::persist,audit,log);}public ModuleCode moduleCode(){return ModuleCode.CIQ;}public CollectorCode collectorCode(){return CollectorCode.CIQ_VMS;}public CollectionResult collect(CollectionContext c){return support.collect(c);}}
